using Microsoft.EntityFrameworkCore;
namespace Society.Api;

public static class MembershipModel
{
    static void Tenant<T>(ModelBuilder b) where T : class { b.Entity<T>().HasAlternateKey("TenantId", "Id"); b.Entity<T>().HasOne<Tenant>().WithMany().HasForeignKey("TenantId").OnDelete(DeleteBehavior.Restrict); }
    static void Ref<T, TTarget>(ModelBuilder b, string field) where T : class where TTarget : class { b.Entity<T>().HasOne<TTarget>().WithMany().HasForeignKey("TenantId", field).HasPrincipalKey("TenantId", "Id").OnDelete(DeleteBehavior.Restrict); }
    public static void Configure(ModelBuilder b)
    {
        b.Entity<Person>().HasIndex(x => x.UserId).IsUnique(); b.Entity<Person>().HasOne<Account>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); b.Entity<Person>().Property(x => x.Revision).IsConcurrencyToken();
        Tenant<MembershipCategory>(b); Tenant<Membership>(b); Tenant<MembershipPolicyRecord>(b); Tenant<MemberApplication>(b); Tenant<MembershipDecision>(b); Tenant<MembershipHistory>(b); Tenant<MemberInvitation>(b); Tenant<MembershipTransfer>(b); Tenant<OfficerPosition>(b); Tenant<OfficerAppointment>(b); Tenant<LeadershipHandover>(b); Tenant<Committee>(b); Tenant<CommitteeMembership>(b); Tenant<MemberDocument>(b); Tenant<MemberImportJob>(b); Tenant<MemberImportRow>(b); Tenant<MemberSavedView>(b);
        b.Entity<MembershipCategory>().HasIndex(x => new { x.TenantId, x.Name }).IsUnique(); Ref<Assignment, Membership>(b, "MembershipId"); Ref<Membership, Unit>(b, "ChapterId"); Ref<Membership, MembershipCategory>(b, "CategoryId"); b.Entity<Membership>().HasOne<Person>().WithMany().HasForeignKey(x => x.PersonId).OnDelete(DeleteBehavior.Restrict); b.Entity<Membership>().HasIndex(x => new { x.TenantId, x.Number }).IsUnique(); b.Entity<Membership>().HasIndex(x => new { x.TenantId, x.PersonId, x.ChapterId }).IsUnique().HasFilter("\"Status\" NOT IN ('Closed','Transferred')"); b.Entity<Membership>().HasIndex(x => new { x.TenantId, x.ChapterId, x.Status, x.JoinedAt }); b.Entity<Membership>().Property(x => x.Privacy).HasColumnType("jsonb"); b.Entity<Membership>().Property(x => x.Revision).IsConcurrencyToken();
        Ref<MembershipPolicyRecord, Unit>(b, "ChapterId"); Ref<MembershipPolicyRecord, Level>(b, "DirectoryLevelId"); b.Entity<MembershipPolicyRecord>().Property(x => x.ApprovalStages).HasColumnType("jsonb"); b.Entity<MembershipPolicyRecord>().Property(x => x.Revision).IsConcurrencyToken();
        Ref<MemberApplication, Unit>(b, "ChapterId"); Ref<MemberApplication, MembershipCategory>(b, "CategoryId"); Ref<MemberApplication, Membership>(b, "MembershipId"); b.Entity<MemberApplication>().HasOne<Account>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); b.Entity<MemberApplication>().HasIndex(x => new { x.TenantId, x.UserId, x.ChapterId }).IsUnique().HasFilter("\"Status\" NOT IN ('Rejected','Withdrawn')"); b.Entity<MemberApplication>().HasIndex(x => new { x.TenantId, x.ChapterId, x.Status, x.CreatedAt }); b.Entity<MemberApplication>().Property(x => x.Stages).HasColumnType("jsonb"); b.Entity<MemberApplication>().Property(x => x.Revision).IsConcurrencyToken();
        Ref<MembershipDecision, MemberApplication>(b, "ApplicationId"); Ref<MembershipDecision, Unit>(b, "OrganizationId"); b.Entity<MembershipDecision>().HasIndex(x => new { x.TenantId, x.ApplicationId, x.Sequence }).IsUnique(); Ref<MembershipHistory, Membership>(b, "MembershipId"); b.Entity<MembershipHistory>().HasIndex(x => new { x.TenantId, x.MembershipId, x.At });
        Ref<MemberInvitation, Unit>(b, "ChapterId"); Ref<MemberInvitation, MembershipCategory>(b, "CategoryId"); b.Entity<MemberInvitation>().HasOne<Person>().WithMany().HasForeignKey(x => x.PersonId).OnDelete(DeleteBehavior.Restrict); b.Entity<MemberInvitation>().HasIndex(x => x.TokenHash).IsUnique();
        Ref<MembershipTransfer, Membership>(b, "MembershipId"); Ref<MembershipTransfer, Unit>(b, "SourceId"); Ref<MembershipTransfer, Unit>(b, "DestinationId"); b.Entity<MembershipTransfer>().Property(x => x.Revision).IsConcurrencyToken(); b.Entity<MembershipTransfer>().HasIndex(x => new { x.TenantId, x.MembershipId }).IsUnique().HasFilter("\"Status\" NOT IN ('Rejected','Effective')");
        Ref<OfficerPosition, GovernanceRole>(b, "RoleId"); b.Entity<OfficerPosition>().HasIndex(x => new { x.TenantId, x.Name }).IsUnique(); Ref<OfficerAppointment, Membership>(b, "MembershipId"); Ref<OfficerAppointment, Unit>(b, "UnitId"); Ref<OfficerAppointment, OfficerPosition>(b, "PositionId"); b.Entity<OfficerAppointment>().HasOne<Assignment>().WithMany().HasForeignKey(x => x.AssignmentId).OnDelete(DeleteBehavior.Restrict); b.Entity<OfficerAppointment>().HasIndex(x => new { x.TenantId, x.UnitId, x.PositionId, x.StartsAt, x.EndsAt }); b.Entity<OfficerAppointment>().Property(x => x.Revision).IsConcurrencyToken();
        Ref<LeadershipHandover, OfficerAppointment>(b, "OutgoingId"); Ref<LeadershipHandover, OfficerAppointment>(b, "IncomingId"); b.Entity<LeadershipHandover>().Property(x => x.Revision).IsConcurrencyToken(); Ref<Committee, Unit>(b, "UnitId"); b.Entity<Committee>().Property(x => x.Revision).IsConcurrencyToken(); Ref<CommitteeMembership, Committee>(b, "CommitteeId"); Ref<CommitteeMembership, Membership>(b, "MembershipId"); b.Entity<CommitteeMembership>().HasIndex(x => new { x.TenantId, x.CommitteeId, x.MembershipId }).IsUnique().HasFilter("\"EndsAt\" IS NULL"); Ref<MemberDocument, Membership>(b, "MembershipId"); Ref<MemberDocument, MemberApplication>(b, "ApplicationId"); Ref<MemberImportJob, Unit>(b, "ChapterId"); Ref<MemberImportJob, MembershipCategory>(b, "CategoryId"); Ref<MemberImportRow, MemberImportJob>(b, "JobId"); Ref<MemberImportRow, Membership>(b, "MembershipId"); b.Entity<MemberImportRow>().HasIndex(x => new { x.TenantId, x.JobId, x.Row }).IsUnique(); b.Entity<MemberImportJob>().HasIndex(x => new { x.Status, x.CreatedAt });
    }
}
